INSERT INTO `batch_reports` (`id`, `name`, `query`, `template`, `order`, `report_id`, `modified_user_id`, `modified`, `created_user_id`, `created`) VALUES
(11, 'Institution Site List', '$data = $this->InstitutionSite->find(''all'',array(''fields''=>array(''InstitutionSite.Code AS Code'',''InstitutionSite.name AS InstitutionName'',''InstitutionSite.address AS Address'',''InstitutionSite.postal_code AS PostalCode'',''InstitutionSite.contact_person AS ContactPerson'',''InstitutionSite.telephone AS Telephone'',''InstitutionSite.fax AS Fax'',''InstitutionSite.email AS Email'',''InstitutionSite.website AS Website'',''InstitutionSite.date_opened AS DateOpened'',''InstitutionSite.date_closed AS DateClosed'',''InstitutionSite.longitude AS Longitude'',''InstitutionSite.latitude AS Latitude'',''Area.name AS AreaName'',''InstitutionSiteLocality.name AS Locality'',''InstitutionSiteType.name AS SiteType'',''InstitutionSiteOwnership.name AS Ownership'',''InstitutionSiteStatus.name AS Status''),{cond}));', 'Code,InstitutionName,Address,PostalCode,ContactPerson,Telephone,Fax,Email,Website,DateOpened,DateClosed,Longitude,Latitude,AreaName,Locality,SiteType,Ownership,Status', 1, 11, NULL, NULL, 1, '0000-00-00 00:00:00'),
(13, 'Institution Site Custom Field Report', '$this->InstitutionSiteCustomValue->formatResult=true;\n$data = $this->InstitutionSiteCustomValue->find(''all'',array(\n''recursive''=>-1,\n''fields''=>array(''InstitutionSite.name AS InstitutionName'',''InstitutionSiteCustomField.name AS Information'',''InstitutionSiteCustomField.type AS Type'',''InstitutionSiteCustomValue.value AS Value'',''InstitutionSiteCustomFieldOption.value AS Option''),\n''joins''=>array(\n	array(\n		''table'' => ''institution_site_custom_fields'',\n		''alias'' => ''InstitutionSiteCustomField'',\n		''conditions'' => array(''InstitutionSiteCustomValue.institution_site_custom_field_id = InstitutionSiteCustomField.id'')\n	),\n	array(\n		''table'' => ''institution_site_custom_field_options'',\n		''alias'' => ''InstitutionSiteCustomFieldOption'',\n		''type'' => ''LEFT'',\n		''conditions'' => array(''InstitutionSiteCustomValue.value = InstitutionSiteCustomFieldOption.id'')\n	),\n	array(\n		''table'' => ''institution_sites'',\n		''alias'' => ''InstitutionSite'',\n		''conditions'' => array(''InstitutionSiteCustomValue.institution_site_id = InstitutionSite.id'')\n	)\n),\n''order''=>array(''InstitutionSite.id'', ''InstitutionSiteCustomField.id''),\n{cond}));\n\nforeach($data as $key => &$value) { \nif ($value[''Type''] != 2 && $value[''Type''] != 5 && $value[''Type''] != 1) { \n$value[''Value''] = $value[''Option'']; }}', 'InstitutionName,Information,Value', 1, 13, NULL, NULL, 1, '0000-00-00 00:00:00'),
(14, 'Institution Site Bank Accounts', '$data = $this->InstitutionSiteBankAccount->find(''all'',array(''fields''=>array(''InstitutionSite.name AS InstitutionName'',''InstitutionSiteBankAccount.account_name AS BankAccountName'',''InstitutionSiteBankAccount.account_number AS BankAccountNumber'',''InstitutionSiteBankAccount.active AS BankAccountActive'',''BankBranch.name AS BankBranchName''),{cond}));', 'InstitutionName,BankAccountName,BankAccountNumber,BankAccountActive,BankBranchName', 1, 14, NULL, NULL, 1, '0000-00-00 00:00:00'),
(15, 'Institution Site Programmes', '$this->InstitutionSiteProgramme->formatResult = true;$data = $this->InstitutionSiteProgramme->find(''all'',array(''recursive''=>-1,''fields''=>array(''InstitutionSite.name AS InstitutionName'',''SchoolYear.name AS SchoolYear'',''EducationProgramme.name AS EducationProgrammeName''),\n''joins''=>array(array(''table'' => ''school_years'',''alias'' => ''SchoolYear'',''conditions'' => array(''InstitutionSiteProgramme.school_year_id = SchoolYear.id'')),array(''table'' => ''education_programmes'',''alias'' => ''EducationProgramme'',''conditions'' => array(''InstitutionSiteProgramme.education_programme_id = EducationProgramme.id'')),array(''table'' => ''institution_sites'',''alias'' => ''InstitutionSite'',''conditions'' => array(''InstitutionSiteProgramme.institution_site_id = InstitutionSite.id''))),\n''conditions''=>array(''InstitutionSiteProgramme.status = 1''),\n{cond}));', 'InstitutionName,SchoolYear,EducationProgrammeName', 1, 15, NULL, NULL, 1, '0000-00-00 00:00:00'),
(21, 'Verification Report', '$this->InstitutionSite->formatResult = true;\r\n$data = $this->InstitutionSite->find(''all'', array(\r\n	''recursive'' => -1,\r\n	''fields'' => array(\r\n		''InstitutionSite.code AS InstitutionCode'',\r\n		''InstitutionSite.name AS InstitutionName'',\r\n		''SchoolYear.name AS SchoolYear'',\r\n		"IF(CensusVerification.status=1, ''Verified'', ''Not Verified'') AS Status",\r\n		"CONCAT(SecurityUser.first_name, '' '', SecurityUser.last_name) AS LastUpdatedBy"\r\n	),\r\n	''joins'' => array(\r\n		array(\r\n			''table'' => ''school_years'',\r\n			''alias'' => ''SchoolYear'',\r\n			''type'' => ''CROSS'',\r\n			''conditions'' => array(''1 = 1'')\r\n		),\r\n		array(\r\n			''table'' => ''census_verifications'',\r\n			''alias'' => ''CensusVerification'',\r\n			''type'' => ''LEFT'',\r\n			''conditions'' => array(\r\n				''CensusVerification.institution_site_id = InstitutionSite.id'',\r\n				''CensusVerification.school_year_id = SchoolYear.id''\r\n			)\r\n		),\r\n		array(\r\n			''table'' => ''census_verifications'',\r\n			''alias'' => ''CensusVerification2'',\r\n			''type'' => ''LEFT'',\r\n			''conditions'' => array(\r\n				''CensusVerification2.school_year_id = CensusVerification.school_year_id'',\r\n				''CensusVerification2.institution_site_id = CensusVerification.institution_site_id'',\r\n				''CensusVerification2.created > CensusVerification.created''\r\n			)\r\n		),\r\n		array(\r\n			''table'' => ''security_users'',\r\n			''alias'' => ''SecurityUser'',\r\n			''type'' => ''LEFT'',\r\n			''conditions'' => array(''SecurityUser.id = CensusVerification.created_user_id'')\r\n		)\r\n	),\r\n	''order'' => array(''InstitutionSite.name'', ''SchoolYear.name'', ''CensusVerification.created''),\r\n	''conditions'' => array(''CensusVerification2.id IS NULL''),\r\n	{cond}\r\n));', 'InstitutionCode,InstitutionName,SchoolYear,Status,LastUpdatedBy', 1, 21, NULL, NULL, 1, '0000-00-00 00:00:00'),
(22, 'Student Report', '$this->CensusStudent->formatResult = true; \n$data = $this->CensusStudent->find(''all'',array(\n''recursive'' => -1, \n''fields''=>array(''SchoolYear.name AS AcademicYear'',''InstitutionSite.name AS InstitutionName'',''EducationGrade.name AS EducationGradeName'',''StudentCategory.name AS Category'',''Gender.name AS Gender'',''CensusStudent.value AS Student''),\n''joins''=>array(\n	array(\n		''table'' => ''school_years'',\n		''alias'' => ''SchoolYear'',\n		''conditions'' => array(''CensusStudent.school_year_id = SchoolYear.id'')\n	),\n	array(\n		''table'' => ''institution_sites'',\n		''alias'' => ''InstitutionSite'',\n		''conditions'' => array(''CensusStudent.institution_site_id = InstitutionSite.id'')\n	),\n	array(\n		''table'' => ''education_grades'',\n		''alias'' => ''EducationGrade'',\n		''conditions'' => array(''CensusStudent.education_grade_id = EducationGrade.id'')\n	),\n	array(\n		''table'' => ''student_categories'',\n		''alias'' => ''StudentCategory'',\n		''conditions'' => array(''CensusStudent.student_category_id = StudentCategory.id'')\n	),\n	array(\n		''table'' => ''field_option_values'',\n		''alias'' => ''Gender'',\n		''conditions'' => array(''CensusStudent.gender_id = Gender.id'')\n	)\n),\n''order'' => array(''SchoolYear.name'', ''InstitutionSite.id'', ''EducationGrade.order'', ''StudentCategory.order'', ''Gender.id''),\n{cond}));', 'AcademicYear,InstitutionName,EducationGradeName,Category,Gender,Student', 1, 22, NULL, NULL, 1, '0000-00-00 00:00:00'),
(24, 'Training Report', '$data = $this->CensusTeacherTraining->find(''all'',array(''fields''=>array(''SchoolYear.name AS AcademicYear'',''InstitutionSite.name AS InstitutionName'',''EducationLevel.name AS EducationLevelName'',''CensusTeacherTraining.male AS Male'',''CensusTeacherTraining.female AS Female''),{cond}));', 'AcademicYear,InstitutionName,EducationLevelName,Male,Female', 1, 24, NULL, NULL, 1, '0000-00-00 00:00:00'),
(25, 'Staff Report', '\n$this->CensusStaff->formatResult = true;\n$data = $this->CensusStaff->find(''all'',array(\n''recursive''=>-1,\n''fields''=>array(''SchoolYear.name AS AcademicYear'',''InstitutionSite.name AS InstitutionName'',''StaffPositionTitle.name AS Position'',''Gender.name AS Gender'',''CensusStaff.value AS Staff''),\n''joins'' => array(\narray(''table'' => ''staff_position_titles'',''alias'' => ''StaffPositionTitle'',''conditions'' => array(''CensusStaff.staff_position_title_id = StaffPositionTitle.id'')),\narray(''table'' => ''field_option_values'',''alias'' => ''Gender'',''conditions'' => array(''CensusStaff.gender_id = Gender.id'')),\narray(''table'' => ''institution_sites'',''alias'' => ''InstitutionSite'',''conditions'' => array(''CensusStaff.institution_site_id = InstitutionSite.id'')),\narray(''table'' => ''school_years'',''alias'' => ''SchoolYear'',''conditions'' => array(''CensusStaff.school_year_id = SchoolYear.id''))\n),\n''order'' => array(''SchoolYear.name'', ''InstitutionSite.id'', ''StaffPositionTitle.id'', ''Gender.id''), {cond} ));', 'AcademicYear,InstitutionName,Position,Gender,Staff', 1, 25, NULL, NULL, 1, '0000-00-00 00:00:00'),
(26, 'Class Report', '$data = $this->CensusClass->find(''all'', array(\r\n			''recursive'' => -1,\r\n			''fields'' => array(\r\n				''SchoolYear.name AS AcademicYear'',\r\n				''InstitutionSite.name AS InstitutionName'',\r\n				''CensusClass.classes AS Classes'',\r\n				''CensusClass.seats AS Seats''\r\n			),\r\n			''joins'' => array(\r\n				array(\r\n					''table'' => ''institution_sites'',\r\n					''alias'' => ''InstitutionSite'',\r\n					''conditions'' => array(''InstitutionSite.id = CensusClass.institution_site_id'')\r\n				),\r\n				array(\r\n					''table'' => ''school_years'',\r\n					''alias'' => ''SchoolYear'',\r\n					''conditions'' => array(''SchoolYear.id = CensusClass.school_year_id'')\r\n				)\r\n			),{cond}\r\n		));', 'AcademicYear,InstitutionName,Classes,Seats', 1, 26, NULL, NULL, 1, '0000-00-00 00:00:00'),
(27, 'Graduate Report', '$CensusGraduate = ClassRegistry::init(''CensusGraduate'');\r\n$CensusGraduate->formatResult = true;\r\n		$data = $CensusGraduate->find(''all'', array(\r\n			''recursive'' => -1,\r\n			''fields'' => array(\r\n				''SchoolYear.name AS AcademicYear'',\r\n				''InstitutionSite.name AS InstitutionName'',\r\n				''EducationProgramme.name AS EducationProgramme'',\r\n				''CensusGraduate.male AS Male'',\r\n				''CensusGraduate.female AS Female''\r\n			),\r\n			''joins'' => array(\r\n				array(\r\n					''table'' => ''institution_sites'',\r\n					''alias'' => ''InstitutionSite'',\r\n					''conditions'' => array(''InstitutionSite.id = CensusGraduate.institution_site_id'')\r\n				),\r\n				array(\r\n					''table'' => ''school_years'',\r\n					''alias'' => ''SchoolYear'',\r\n					''conditions'' => array(''SchoolYear.id = CensusGraduate.school_year_id'')\r\n				),\r\n				array(\r\n					''table'' => ''education_programmes'',\r\n					''alias'' => ''EducationProgramme'',\r\n					''conditions'' => array(''EducationProgramme.id = CensusGraduate.education_programme_id'')\r\n				)\r\n			),{cond}\r\n		));', 'AcademicYear,InstitutionName,EducationProgramme,Male,Female', 1, 27, NULL, NULL, 1, '0000-00-00 00:00:00'),
